WildlifeKnockout = WildlifeKnockout or {} WildlifeKnockout._type = WildlifeKnockout function WildlifeKnockout:Faint() self.player = GetLocalPlayerId() SetScriptedDeath(1) self.died = CScriptCallbackSystem_GetInstance():RegisterEventCallback(self.player, self, "Event_Died", "PlayerDied") System:Log("WildlifeKnockout: Faint, PlayerDied callback " .. tostring(self.died)) self:Hit() end function WildlifeKnockout:Die() self.player = GetLocalPlayerId() BlockBuddyRescue() self:After(1, "Unblock") self:Hit() end function WildlifeKnockout:Hit() SendPierceStimNoOrigin(self.player, 32) SendPierceStimNoOrigin(self.player, 32) end function WildlifeKnockout:After(seconds, method) local delays = CDominoDelayManager_GetInstance() delays:SendCommand(delays:CreateDelay(seconds, self, method), "start") end function WildlifeKnockout:Unblock() UnblockBuddyRescue() end function WildlifeKnockout:Event_Died() System:Log("WildlifeKnockout: PlayerDied") CScriptCallbackSystem_GetInstance():RemoveCallback(self.player, self.died) self:After(2, "WakeUp") end function WildlifeKnockout:WakeUp() local domino = CDominoManager_GetInstance() domino:SendCommandEventToEntity(self.player, "SetupPlayerForAnchorAnim", 1) self.stood = CScriptCallbackSystem_GetInstance():RegisterEventCallback(self.player, self, "Event_StoodUp", "FinishedPlayAnim") local sent = domino:SendCommandEventToEntity2(self.player, "PlayAnim", self, "AnimCommandSent", "pawn_generic_desertgetup", 0, 1) System:Log("WildlifeKnockout: WakeUp, PlayAnim sent " .. tostring(sent)) domino:SendRegisteredEventToEntity(self.player, "CFCXCountersComponentPlayerSP_HealingDone") SetScriptedDeath(0) end function WildlifeKnockout:Event_StoodUp() System:Log("WildlifeKnockout: stood up") CScriptCallbackSystem_GetInstance():RemoveCallback(self.player, self.stood) SetPlayerActionMap("default") end function WildlifeKnockout:AnimCommandSent() end
